func TestAgreementSharedUnusedSource(t *testing.T) {
	t.Parallel()
	witnesses := agreementSharedUnusedWitnesses()
	for wi := range witnesses {
		w := &witnesses[wi]
		t.Run(w.Name, func(t *testing.T) {
			t.Parallel()
			native := agreementNativeOwnerReading(w.Body)
			check := agreementNativeCheckReading(w.Body, native)
			tree := agreementNativeProseAddressTreeReading(w.Body, nil)
			if diff := cmp.Diff(w.Native, native); diff != "" {
				t.Fatalf("caught: complete shared unused native source (-want +got):\n%s", diff)
			}
			if diff := cmp.Diff(w.Check, check); diff != "" {
				t.Fatalf("caught: complete shared unused physical fields (-want +got):\n%s", diff)
			}
			if diff := cmp.Diff(w.Tree, tree); diff != "" {
				t.Fatalf("caught: complete shared unused declaration trees (-want +got):\n%s", diff)
			}
			if !cmp.Equal(judge.LinkTargets(w.Body), w.Targets) || !cmp.Equal(agreementNativeCodePayloadSites(w.Body), w.Sites) || !cmp.Equal(agreementNativeHTMLAddressSites(w.Body), w.HTML) {
				t.Fatal("caught: complete shared unused source rosters")
			}
			for vi := range w.Variants {
				v := &w.Variants[vi]
				owners, ok := agreementSharedUnusedOwners(native, &check, &tree, v.Target)
				if !ok || !cmp.Equal(owners, v.Owners) {
					t.Fatal("caught: complete shared unused native owner map")
				}
				private, changes, valid := agreementSharedUnusedPrivate(w.Body, v.Target, native, &check, &tree)
				if !valid || private != v.Body || !cmp.Equal(changes, v.Changes) {
					t.Fatal("caught: exact shared unused target-only projection")
				}
				projected := agreementNativeOwnerReading(private)
				if !cmp.Equal(projected, native) || !cmp.Equal(agreementNativeProseAddressTreeReading(private, nil), tree) || !cmp.Equal(agreementNativeCodePayloadSites(private), w.Sites) || !cmp.Equal(agreementNativeHTMLAddressSites(private), w.HTML) {
					t.Fatal("caught: unchanged whole shared unused declarations")
				}
				pc := agreementNativeCheckReading(private, projected)
				if !cmp.Equal(pc, v.Check) || !cmp.Equal(judge.LinkTargets(private), v.Targets) {
					t.Fatal("caught: complete shared unused private check ledger")
				}
			}
		})
	}
}

func TestAgreementSharedUnusedPublic(t *testing.T) {
	t.Parallel()
	witnesses := agreementSharedUnusedWitnesses()
	for wi := range witnesses {
		w := &witnesses[wi]
		t.Run(w.Name, func(t *testing.T) {
			t.Parallel()
			variants := append([]agreementSharedUnusedVariant{{Body: w.Body, Signatures: w.Signatures}}, w.Variants...)
			for vi := range variants {
				v := &variants[vi]
				c := agreementCase{Body: v.Body}
				raw, page := agreementIsolatedPage(t, c)
				parts, ok := agreementCodeWindowParts(raw.HTML)
				if !ok || !cmp.Equal(page, w.Page) || !cmp.Equal(parts, w.Parts) {
					t.Fatal("caught: complete unchanged shared unused public ledger")
				}
				failures := agreementPageFailures(v.Body, &raw, &page)
				failures = append(failures, agreementFragmentFailures(t, []agreementCase{c}, []agreementHTML{page})[0]...)
				if !maps.Equal(agreementMixedCurrent(failures), v.Signatures) {
					t.Fatal("caught: complete shared unused P0-P4 signed pools")
				}
			}
		})
	}
}

func agreementSharedUnusedDifference(c agreementCase, f *agreementFailure, raw string, page *agreementHTML, failures []agreementFailure) (kind, authority, wrong string) {
	if f == nil || page == nil || c.Title != "" || len(c.Companions) != 0 || f.Property != "P1" || f.Identity != "citation-occurrences" || f.Direction != "judge-only" || f.Multiplicity < 1 || f.Fragment != "" || f.Cut != "" || f.PagePresent || f.JudgeAccepted || f.ExcerptFound {
		return "", "", ""
	}
	witnesses := agreementSharedUnusedWitnesses()
	for wi := range witnesses {
		w := &witnesses[wi]
		if c.Body != w.Body {
			continue
		}
		if w.Selected[agreementSignature(f)] != 1 {
			return "", "", ""
		}
		native := agreementNativeOwnerReading(c.Body)
		check := agreementNativeCheckReading(c.Body, native)
		tree := agreementNativeProseAddressTreeReading(c.Body, nil)
		parts, pok := agreementCodeWindowParts(raw)
		if !pok || !cmp.Equal(native, w.Native) || !cmp.Equal(check, w.Check) || !cmp.Equal(tree, w.Tree) || !cmp.Equal(agreementNativeCodePayloadSites(c.Body), w.Sites) || !cmp.Equal(agreementNativeHTMLAddressSites(c.Body), w.HTML) || !cmp.Equal(judge.LinkTargets(c.Body), w.Targets) || !cmp.Equal(parts, w.Parts) || !cmp.Equal(*page, w.Page) || !maps.Equal(agreementMixedCurrent(failures), w.Signatures) {
			return "", "", ""
		}
		for vi := range w.Variants {
			v := &w.Variants[vi]
			if v.Target != f.Tuple.Target {
				continue
			}
			owners, ok := agreementSharedUnusedOwners(native, &check, &tree, v.Target)
			private, changes, valid := agreementSharedUnusedPrivate(c.Body, v.Target, native, &check, &tree)
			if !ok || !valid || len(owners) != f.Multiplicity || !cmp.Equal(owners, v.Owners) || private != v.Body || !cmp.Equal(changes, v.Changes) {
				return "", "", ""
			}
			return "debt", "#1011 stage 5", "judge"
		}
		return "", "", ""
	}
	return "", "", ""
}

func TestAgreementSharedUnusedCausalPools(t *testing.T) {
	t.Parallel()
	witnesses := agreementSharedUnusedWitnesses()
	for wi := range witnesses {
		w := &witnesses[wi]
		t.Run(w.Name, func(t *testing.T) {
			t.Parallel()
			c := agreementCase{Body: w.Body}
			raw, page := agreementIsolatedPage(t, c)
			failures := agreementPageFailures(w.Body, &raw, &page)
			failures = append(failures, agreementFragmentFailures(t, []agreementCase{c}, []agreementHTML{page})[0]...)
			selected := make(map[string]int)
			for vi := range w.Variants {
				v := &w.Variants[vi]
				var p0, p1 agreementFailure
				n0, n1 := 0, 0
				for _, f := range failures {
					if f.Tuple.Target != v.Target {
						continue
					}
					if f.Property == "P0" && f.Identity == "diagnostic-html" && f.Direction == "diagnostic-only" && f.Tuple.Section == "" {
						p0 = f
						n0++
					}
					if f.Property == "P1" && f.Identity == "citation-occurrences" && f.Direction == "judge-only" {
						p1 = f
						n1++
					}
				}
				count := len(v.Owners)
				if n0 != 1 || n1 != 1 || count < 1 || p1.Multiplicity != count || p0.Multiplicity < count {
					t.Fatal("caught: shared unused signed counts bind every selected native owner")
				}
				selected[agreementSignature(&p1)]++
				expected := maps.Clone(w.Signatures)
				delete(expected, agreementSignature(&p1))
				private := p1
				private.Tuple.Target = strings.Repeat("q", len(v.Target))
				expected[agreementSignature(&private)]++
				delete(expected, agreementSignature(&p0))
				remainder := p0
				remainder.Multiplicity -= count
				if remainder.Multiplicity > 0 {
					expected[agreementSignature(&remainder)]++
				}
				diagnostic := p0
				diagnostic.Tuple.Target = private.Tuple.Target
				diagnostic.Multiplicity = count
				expected[agreementSignature(&diagnostic)]++
				if !maps.Equal(expected, v.Signatures) {
					t.Fatal("caught: exact shared unused P0/P1 substitution preserves every other P0-P4 member")
				}
				kind, authority, wrong := agreementSharedUnusedDifference(c, &p1, raw.HTML, &page, failures)
				if kind != "debt" || authority != "#1011 stage 5" || wrong != "judge" {
					t.Fatal("caught: exact selected shared unused P1 debt")
				}
			}
			if !maps.Equal(selected, w.Selected) {
				t.Fatal("caught: whole selected shared unused receipt set")
			}
		})
	}
}

func TestAgreementSharedUnusedWholeFields(t *testing.T) {
	t.Parallel()
	witnesses := agreementSharedUnusedWitnesses()
	for wi := range witnesses {
		w := &witnesses[wi]
		t.Run(w.Name, func(t *testing.T) {
			t.Parallel()
			for vi := range w.Variants {
				v := &w.Variants[vi]
				expected := w.Check
				expected.Fields = slices.Clone(w.Check.Fields)
				owned := make(map[int]bool)
				for _, o := range v.Owners {
					if owned[o.Field] {
						t.Fatal("caught: unique shared unused physical ownership")
					}
					owned[o.Field] = true
				}
				selected := make(map[int]agreementMixedRename)
				for _, change := range v.Changes {
					if _, exists := selected[change.Field]; exists {
						t.Fatal("caught: unique shared unused physical substitution")
					}
					selected[change.Field] = change
				}
				bytes := []byte(w.Body)
				for fi, field := range w.Check.Fields {
					active := !field.Code && !field.Comment && !field.Escaped && field.DefinitionOwner >= 0 && slices.Contains(field.Targets, v.Target)
					change, changed := selected[fi]
					if active != owned[fi] || active != changed {
						t.Fatal("caught: whole active shared unused field selection")
					}
					if !active {
						continue
					}
					if change.Old != v.Target || change.New != strings.Repeat("q", len(v.Target)) || change.Span.Start < field.Span.Start+2 || change.Span.Stop > field.Span.Stop-2 || w.Body[change.Span.Start:change.Span.Stop] != v.Target {
						t.Fatal("caught: exact shared unused substitution bounds")
					}
					copy(bytes[change.Span.Start:change.Span.Stop], change.New)
					start := change.Span.Start - field.Span.Start
					stop := change.Span.Stop - field.Span.Start
					expected.Fields[fi].Word = field.Word[:start] + change.New + field.Word[stop:]
					expected.Fields[fi].Targets = []string{change.New}
				}
				expected.Targets = nil
				for _, field := range expected.Fields {
					if !field.Code && !field.Comment && !field.Escaped {
						expected.Targets = append(expected.Targets, field.Targets...)
					}
				}
				if string(bytes) != v.Body || !cmp.Equal(expected, v.Check) {
					t.Fatal("caught: only the complete selected shared unused word and target set changes")
				}
			}
		})
	}
}

func TestAgreementSharedUnusedDifferences(t *testing.T) {
	t.Parallel()
	witnesses := agreementSharedUnusedWitnesses()
	for wi := range witnesses {
		w := &witnesses[wi]
		t.Run(w.Name, func(t *testing.T) {
			t.Parallel()
			c := agreementCase{Body: w.Body}
			raw, page := agreementIsolatedPage(t, c)
			failures := agreementPageFailures(w.Body, &raw, &page)
			failures = append(failures, agreementFragmentFailures(t, []agreementCase{c}, []agreementHTML{page})[0]...)
			seen := 0
			for _, f := range failures {
				if w.Selected[agreementSignature(&f)] != 1 {
					continue
				}
				seen++
				k, a, v := agreementSharedUnusedDifference(c, &f, raw.HTML, &page, failures)
				if k != "debt" || a != "#1011 stage 5" || v != "judge" {
					t.Fatal("caught: shared unused lost its declared authority")
				}
				for _, alter := range []struct {
					Name   string
					Change func(*agreementFailure)
				}{
					{"property", func(f *agreementFailure) { f.Property = "P2" }}, {"identity", func(f *agreementFailure) { f.Identity = "other" }}, {"direction", func(f *agreementFailure) { f.Direction = "other" }}, {"target", func(f *agreementFailure) { f.Tuple.Target = "outside" }}, {"role", func(f *agreementFailure) { f.Tuple.SourceRole = "other" }}, {"state", func(f *agreementFailure) { f.Tuple.State = "other" }}, {"section", func(f *agreementFailure) { f.Tuple.Section = "other" }}, {"multiplicity", func(f *agreementFailure) { f.Multiplicity++ }}, {"cut", func(f *agreementFailure) { f.Cut = "other" }}, {"fragment", func(f *agreementFailure) { f.Fragment = "other" }}, {"page", func(f *agreementFailure) { f.PagePresent = true }}, {"judge", func(f *agreementFailure) { f.JudgeAccepted = true }}, {"excerpt", func(f *agreementFailure) { f.ExcerptFound = true }},
				} {
					t.Run(alter.Name, func(t *testing.T) {
						changed := f
						alter.Change(&changed)
						kind, authority, wrong := agreementSharedUnusedDifference(c, &changed, raw.HTML, &page, failures)
						if kind != "" || authority != "" || wrong != "" {
							t.Fatal("caught: shared unused borrowed another signed face")
						}
					})
				}
				for _, other := range []agreementCase{{Body: w.Body + "\n"}, {Body: w.Body, Title: "A"}, {Body: w.Body, Companions: capturedBodies{"Notes/Other.md": "outside"}}} {
					kind, authority, wrong := agreementSharedUnusedDifference(other, &f, raw.HTML, &page, failures)
					if kind != "" || authority != "" || wrong != "" {
						t.Fatal("caught: shared unused borrowed another complete body or context")
					}
				}
				for i := range failures {
					missing := slices.Delete(slices.Clone(failures), i, i+1)
					k, a, v = agreementSharedUnusedDifference(c, &f, raw.HTML, &page, missing)
					if k != "" || a != "" || v != "" {
						t.Fatal("caught: shared unused borrowed an incomplete whole signed pool")
					}
				}
				extra := append(slices.Clone(failures), f)
				k, a, v = agreementSharedUnusedDifference(c, &f, raw.HTML, &page, extra)
				if k != "" || a != "" || v != "" {
					t.Fatal("caught: shared unused borrowed another whole signed pool")
				}
				changed := page
				changed.Headings = append(slices.Clone(page.Headings), "outside")
				k, a, v = agreementSharedUnusedDifference(c, &f, raw.HTML, &changed, failures)
				if k != "" || a != "" || v != "" {
					t.Fatal("caught: shared unused borrowed another whole public ledger")
				}
				k, a, v = agreementSharedUnusedDifference(c, &f, raw.HTML+"<code>outside</code>", &page, failures)
				if k != "" || a != "" || v != "" {
					t.Fatal("caught: shared unused borrowed changed field-free code text")
				}
			}
			if seen != len(w.Selected) {
				t.Fatal("shared unused selected receipt setup")
			}
		})
	}
}

func TestAgreementSharedUnusedOwnershipRefusals(t *testing.T) {
	witnesses := agreementSharedUnusedWitnesses()
	for wi := range witnesses {
		w := &witnesses[wi]
		for vi := range w.Variants {
			v := &w.Variants[vi]
			owner := v.Owners[0]
			for _, tc := range []struct {
				Name   string
				Change func(*agreementNativeOwnerSource, *agreementNativeCheckSource, *agreementNativeProseAddressTree)
			}{
				{"missing definitions", func(n *agreementNativeOwnerSource, _ *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
					n.Definitions = nil
				}},
				{"invalid tree", func(_ *agreementNativeOwnerSource, _ *agreementNativeCheckSource, r *agreementNativeProseAddressTree) {
					r.Valid = false
				}},
				{"missing roots", func(_ *agreementNativeOwnerSource, _ *agreementNativeCheckSource, r *agreementNativeProseAddressTree) {
					r.Trees = nil
				}},
				{"missing declarations", func(_ *agreementNativeOwnerSource, _ *agreementNativeCheckSource, r *agreementNativeProseAddressTree) {
					r.Definitions = nil
				}},
				{"ambiguous declaration", func(_ *agreementNativeOwnerSource, _ *agreementNativeCheckSource, r *agreementNativeProseAddressTree) {
					for _, d := range r.Definitions {
						if d.Root == owner.Root {
							r.Definitions = append(r.Definitions, d)
							return
						}
					}
				}},
				{"other root kind", func(_ *agreementNativeOwnerSource, _ *agreementNativeCheckSource, r *agreementNativeProseAddressTree) {
					r.Trees[owner.Root][0].Kind = ast.KindDocument.String()
				}},
				{"duplicate physical field", func(_ *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
					c.Fields = append(c.Fields, c.Fields[owner.Field])
				}},
				{"outside definition", func(_ *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
					c.Fields[owner.Field].DefinitionOwner = len(w.Native.Definitions)
				}},
				{"clipped consumed start", func(n *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
					n.Definitions[owner.Definition].Span.Start = c.Fields[owner.Field].Span.Stop
				}},
				{"clipped consumed stop", func(n *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
					n.Definitions[owner.Definition].Span.Stop = c.Fields[owner.Field].Span.Start
				}},
				{"outside field start", func(n *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
					c.Fields[owner.Field].Span.Start = n.Definitions[owner.Definition].Span.Start - 1
				}},
				{"outside field stop", func(n *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
					c.Fields[owner.Field].Span.Stop = n.Definitions[owner.Definition].Span.Stop + 1
				}},
				{"empty field", func(_ *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
					c.Fields[owner.Field].Span.Stop = c.Fields[owner.Field].Span.Start
				}},
				{"outside name", func(n *agreementNativeOwnerSource, _ *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
					n.Definitions[owner.Definition].Name.Start = n.Definitions[owner.Definition].Span.Start - 1
				}},
				{"empty selected set", func(_ *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
					c.Fields = nil
				}},
				{"already check code", func(_ *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
					for _, o := range v.Owners {
						c.Fields[o.Field].Code = true
					}
				}},
				{"comment", func(_ *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
					for _, o := range v.Owners {
						c.Fields[o.Field].Comment = true
					}
				}},
				{"escaped", func(_ *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
					for _, o := range v.Owners {
						c.Fields[o.Field].Escaped = true
					}
				}},
				{"different target", func(_ *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
					for _, o := range v.Owners {
						c.Fields[o.Field].Targets = []string{"other"}
					}
				}},
				{"multiple targets", func(_ *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
					c.Fields[owner.Field].Targets = []string{v.Target, "other"}
				}},
				{"missing definition role", func(_ *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
					for _, o := range v.Owners {
						c.Fields[o.Field].DefinitionOwner = -1
					}
				}},
				{"missing root node", func(_ *agreementNativeOwnerSource, _ *agreementNativeCheckSource, r *agreementNativeProseAddressTree) {
					r.Trees[owner.Root] = nil
				}},
			} {
				t.Run(w.Name+"/"+v.Target+"/"+tc.Name, func(t *testing.T) {
					n := w.Native
					n.Definitions = slices.Clone(n.Definitions)
					c := w.Check
					c.Fields = slices.Clone(c.Fields)
					r := w.Tree
					r.Definitions = slices.Clone(r.Definitions)
					r.Trees = slices.Clone(r.Trees)
					for i := range r.Trees {
						r.Trees[i] = slices.Clone(r.Trees[i])
					}
					tc.Change(&n, &c, &r)
					if _, ok := agreementSharedUnusedOwners(n, &c, &r, v.Target); ok {
						t.Fatal("caught: shared unused source borrowed absent, clipped or ambiguous ownership")
					}
				})
			}
			for _, tc := range []struct {
				Name   string
				Change func(*agreementNativeProseAddressDefinition)
			}{
				{"not found", func(d *agreementNativeProseAddressDefinition) { d.Found = false }},
				{"document root", func(d *agreementNativeProseAddressDefinition) { d.Root = 0 }},
				{"other root", func(d *agreementNativeProseAddressDefinition) { d.Root++ }},
				{"other node", func(d *agreementNativeProseAddressDefinition) { d.Node++ }},
				{"other label", func(d *agreementNativeProseAddressDefinition) { d.Label = "other" }},
				{"other parent", func(d *agreementNativeProseAddressDefinition) { d.Bounds.Parent = "other" }},
				{"other consumed start", func(d *agreementNativeProseAddressDefinition) { d.Bounds.Span.Start++ }},
				{"other consumed stop", func(d *agreementNativeProseAddressDefinition) { d.Bounds.Span.Stop-- }},
				{"other name start", func(d *agreementNativeProseAddressDefinition) { d.Bounds.Label.Start++ }},
				{"other name stop", func(d *agreementNativeProseAddressDefinition) { d.Bounds.Label.Stop-- }},
			} {
				t.Run(w.Name+"/"+v.Target+"/"+tc.Name, func(t *testing.T) {
					r := w.Tree
					r.Definitions = slices.Clone(r.Definitions)
					for i := range r.Definitions {
						if r.Definitions[i].Root == owner.Root {
							tc.Change(&r.Definitions[i])
						}
					}
					if _, ok := agreementSharedUnusedOwners(w.Native, &w.Check, &r, v.Target); ok {
						t.Fatal("caught: shared unused source borrowed another native declaration map")
					}
				})
			}
		}
	}
}

func TestAgreementSharedUnusedPrivateRefusals(t *testing.T) {
	witnesses := agreementSharedUnusedWitnesses()
	for wi := range witnesses {
		w := &witnesses[wi]
		for vi := range w.Variants {
			v := &w.Variants[vi]
			name := w.Name + "/" + v.Target
			t.Run(name+"/private namespace", func(t *testing.T) {
				if _, _, ok := agreementSharedUnusedPrivate(w.Body+"q", v.Target, w.Native, &w.Check, &w.Tree); ok {
					t.Fatal("caught: shared unused private namespace collides")
				}
			})
			for _, target := range []string{"", "outside"} {
				if _, _, ok := agreementSharedUnusedPrivate(w.Body, target, w.Native, &w.Check, &w.Tree); ok {
					t.Fatal("caught: shared unused projection borrowed another target set")
				}
			}
			for _, o := range v.Owners {
				fi := o.Field
				field := w.Check.Fields[fi]
				t.Run(name+"/changed physical word", func(t *testing.T) {
					body := []byte(w.Body)
					body[field.Span.Start+2] = 'X'
					if _, _, ok := agreementSharedUnusedPrivate(string(body), v.Target, w.Native, &w.Check, &w.Tree); ok {
						t.Fatal("caught: shared unused projection borrowed changed physical word bytes")
					}
				})
				t.Run(name+"/clipped body", func(t *testing.T) {
					if _, _, ok := agreementSharedUnusedPrivate(w.Body[:field.Span.Start], v.Target, w.Native, &w.Check, &w.Tree); ok {
						t.Fatal("caught: shared unused projection borrowed fields beyond the body")
					}
				})
				for _, edge := range []string{"prefix", "suffix"} {
					t.Run(name+"/"+edge, func(t *testing.T) {
						check := w.Check
						check.Fields = slices.Clone(check.Fields)
						word := []byte(field.Word)
						switch edge {
						case "prefix":
							word[0], word[1] = '~', '~'
						case "suffix":
							word[len(word)-2], word[len(word)-1] = '~', '~'
						}
						check.Fields[fi].Word = string(word)
						body := []byte(w.Body)
						copy(body[field.Span.Start:field.Span.Stop], word)
						if _, _, ok := agreementSharedUnusedPrivate(string(body), v.Target, w.Native, &check, &w.Tree); ok {
							t.Fatal("caught: shared unused projection borrowed different field tokens")
						}
					})
				}
			}
			t.Run(name+"/consumed definition beyond body", func(t *testing.T) {
				native := w.Native
				native.Definitions = slices.Clone(native.Definitions)
				tree := w.Tree
				tree.Definitions = slices.Clone(tree.Definitions)
				owner := v.Owners[0]
				native.Definitions[owner.Definition].Span.Stop = len(w.Body) + 1
				for i := range tree.Definitions {
					if tree.Definitions[i].Root == owner.Root {
						tree.Definitions[i].Bounds.Span.Stop = len(w.Body) + 1
					}
				}
				if _, _, ok := agreementSharedUnusedPrivate(w.Body, v.Target, native, &w.Check, &tree); ok {
					t.Fatal("caught: shared unused projection borrowed a consumed definition outside the body")
				}
			})
		}
	}
}
